WITH base AS (SELECT *, CASE WHEN revenue >= 3900 THEN 'High' WHEN revenue >= 1700 THEN 'Medium' ELSE 'Low' END AS revenue_level, DATE_FORMAT(sale_date, 'MMM yyyy') AS sale_date_label FROM store_sales WHERE units > 36) SELECT *, AVG(units) OVER w_ordered AS last3_avg_units, MAX(units) OVER w_ordered AS last3_max_units, COUNT(units) OVER w_ordered AS last3_count_units, MIN(units) OVER w_ordered AS last3_min_units FROM base WHERE product_id IN (2, 8, 9) WINDOW w_ordered AS (PARTITION BY product_id, store_id ORDER BY sale_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW);
